package com.pollhub.controller;
import com.pollhub.dto.*;import com.pollhub.security.*;import com.pollhub.service.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.*;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import java.time.LocalDateTime;import java.util.List;import static org.mockito.Mockito.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(PollController.class) @AutoConfigureMockMvc(addFilters=false) class PollControllerTest{@Autowired MockMvc mvc;@MockitoBean PollService service;@MockitoBean VoteService votes;@MockitoBean JwtAuthenticationFilter filter;@MockitoBean CustomUserDetailsService details;@MockitoBean RestAuthenticationEntryPoint entry;
 @Test void returnsPoll()throws Exception{when(service.get(1L)).thenReturn(new PollResponse(1L,"Test","Opis",true,LocalDateTime.now(),null,2L,"Ana",3L,"Sport",List.of(),0));mvc.perform(get("/api/polls/1").with(user("a"))).andExpect(status().isOk()).andExpect(jsonPath("$.title").value("Test"));}
 @Test void votes()throws Exception{when(votes.vote(eq(1L),any(),eq("a"))).thenReturn(new VoteResponse(4L,1L,3L,LocalDateTime.now()));mvc.perform(post("/api/polls/1/votes").principal(()->"a").contentType("application/json").content("{\"optionId\":3}")).andExpect(status().isCreated()).andExpect(jsonPath("$.optionId").value(3));}}
